import React from "react";

export function Form() {
  const [taskName, setTaskName] = React.useState("");
  const [taslkDescription, setTaskDescription] = React.useState("");
  const [taskDueDate, setTaskDueDate] = React.useState("");
  const [taskStatus, setTaskStatus] = React.useState("Pending");

  const submit_event = (event) => {
    event.preventDefault();
    console.log("Form submitted");
    event.target.reset();
  };
  return (
    <form className="form" onSubmit={submit_event}>
      <label htmlFor="task_name">Task name</label>
      <input id="task_name" name="task_name" type="text" required />
      <button type="submit">Create task</button>
    </form>
  );
}
